/* FORGE approved exercise photography – shoulder external rotation.
 * Source reference: user-approved image from 2026-10-29, with the exercised right
 * hand moving toward the viewer's left, the upper arm remaining at the torso,
 * and the cable routed continuously from pulley to handle.
 * Two movement positions plus one separate anatomy panel, no third movement phase.
 * This file makes no changes to training data or existing image assets.
 */
(function(){
'use strict';
const photoAssets={"Schulter-Außenrotation":["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"]};
const previousExercise=window.forgeExerciseIllustrations;
const previousCatalog=window.forgePublicExercisePictures;
const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function picture(name){
 const assets=photoAssets[name]; if(!assets)return '';
 const labels=['Startposition','Endposition','Beanspruchte Muskelgruppen'];
 return '<div class="forge168-photo-grid" data-forge168-photo="'+safe(name)+'">'+
  assets.map((src,i)=>'<figure class="forge168-photo"><img src="'+src+'" loading="lazy" decoding="async" alt="'+safe(name)+' – '+labels[i]+'" /></figure>').join('')+
  '</div><p class="forge168-photo-note">Den rechten Oberarm am Körper halten und nur den Unterarm nach außen drehen. Kabel und Griff bleiben verbunden. Die Fotos dienen als Orientierung; die Technikhinweise gelten weiterhin.</p>';
}
window.forgeExerciseIllustrations=function(name){return Object.hasOwn(photoAssets,name)?picture(name):(typeof previousExercise==='function'?previousExercise(name):'');};
window.forgePublicExercisePictures=function(name){return Object.hasOwn(photoAssets,name)?picture(name):(typeof previousCatalog==='function'?previousCatalog(name):'');};
window.forge168BatchInfo={names:Object.keys(photoAssets),picture};
function style(){
 if(document.getElementById('forge168PhotoStyle'))return;
 const e=document.createElement('style');e.id='forge168PhotoStyle';e.textContent=`
 .forge168-photo-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:9px 0 12px}
 .forge168-photo{margin:0;min-width:0;border-radius:11px;overflow:hidden;background:#0a161d;border:1px solid #496159}
 .forge168-photo img{width:100%;height:auto;aspect-ratio:auto;object-fit:contain;display:block}
 .forge168-photo:last-child{grid-column:1/-1}
 .forge168-photo:last-child img{max-height:390px;object-fit:contain}
 .forge168-photo-note{font-size:11px!important;color:#a3b9b3!important;line-height:1.48!important;margin:2px 0 12px!important}
 .forge-strength-body:has(.forge168-photo-grid)>.forge159-muscles,
 .forge-strength-body:has(.forge168-photo-grid)>.forge-muscle-map{display:none!important}
 @media(min-width:670px){.forge168-photo-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.forge168-photo:last-child{grid-column:auto}.forge168-photo:last-child img{max-height:none}}
 `;document.head.appendChild(e);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',style,{once:true});else style();
})();